1757	    const vuint32m4_t sign = __riscv_vsll_vx_u32m4(__riscv_vand_vx_u32m4(hz, 0x8000, vl), 16, vl);
1758	    vuint32m4_t       mag  = __riscv_vadd_vx_u32m4(
1759	        __riscv_vsll_vx_u32m4(__riscv_vand_vx_u32m4(hz, 0x7FFF, vl), 13, vl), (uint32_t) 112 << 23, vl);
1760	    const vbool8_t ez = __riscv_vmseq_vx_u32m4_b8(__riscv_vand_vx_u32m4(hz, 0x7C00, vl), 0, vl);
