1776	// ---- Q1_D4: the same row-parallel gemv on nds.vd4dots.vv (XAndesVDot) ------
1777	// Needs the Q1_D4 sign-plane order (repack.h q1_0x64_sign_bit) and
1778	// -march=..._xandesvdot. Only the VLEN>=1024 shape is implemented: e32/m2 is
1779	// then exactly 64 i32 lanes = 64 rows, and the same register group seen as i8
1780	// is 256 bytes = 64 rows x 4 columns, which is the operand shape the
1781	// instruction consumes. Everything else falls through to the generic kernel.
1782	#if defined(Q1_D4) && Q1_D4
1783	
1784	// vd[lane] += sum_{k<4} vs1[4*lane+k] * vs2[4*lane+k], int8 x int8 into i32.
1785	// GCC 14.2 has no intrinsic, so this is inline asm - and that shapes the whole
1786	// helper. Two consequences drive the design, both measured, both gated by
1787	// ./check-vd4dots.sh:
1788	//
1789	// 1. vtype churn (F9). GCC cannot see inside an asm block, so it assumes every
1790	//    block left vtype unknown and re-issues its own vsetvli before the next
1791	//    intrinsic. A one-dot block therefore costs TWO vsetvli, and the kernels
1792	//    also alternate between the byte view (mask load, sign expand) and the
1793	//    32-bit view (broadcast, dot) - 4 vsetvli per dot in the first version,
1794	//    40% of the gemv inner loop, none of it arithmetic. Grouping the two
1795	//    widths in the SOURCE is not enough: the scheduler interleaves them again.
1796	//    So everything at e32 lives inside one block - the broadcasts too - which
1797	//    leaves GCC only e8 work to schedule and pays one vsetvli per four dots.
1798	//
1799	// 2. The broadcast must stay vmv.v.x. Handed the intrinsic, GCC contracts
1800	//    "load a word, splat it" into `vlse32.v vd,(rs1),zero`, and a stride-0
1801	//    strided load is element-serial on this core - 18x slower. Taking the
1802	//    activation quads as plain uint32 GPRs and spelling the splat out here
1803	//    makes that contraction impossible by construction.
1804	//
1805	// Two scratch vectors, not four, so the four dots still overlap while the
1806	// register budget stays clear of the 4 accumulators the gemm needs.
1807	
1808	// gemv: four (weight, activation) pairs chained into one accumulator
1809	static inline vint32m2_t q1_vd4dots_x4_m2(vint32m2_t acc,
1810	        vint8m2_t w0, vint8m2_t w1, vint8m2_t w2, vint8m2_t w3,
1811	        uint32_t u0, uint32_t u1, uint32_t u2, uint32_t u3) {
1812	    vint8m2_t s0, s1;
1813	    asm volatile(
1814	        "vsetvli t0, zero, e32, m2, ta, ma\n\t"
1815	        "vmv.v.x %[s0], %[u0]\n\t"
1816	        "vmv.v.x %[s1], %[u1]\n\t"
1817	        "nds.vd4dots.vv %[acc], %[w0], %[s0]\n\t"
1818	        "nds.vd4dots.vv %[acc], %[w1], %[s1]\n\t"
1819	        "vmv.v.x %[s0], %[u2]\n\t"
1820	        "vmv.v.x %[s1], %[u3]\n\t"
1821	        "nds.vd4dots.vv %[acc], %[w2], %[s0]\n\t"
1822	        "nds.vd4dots.vv %[acc], %[w3], %[s1]"
1823	        : [acc] "+vr" (acc), [s0] "=&vr" (s0), [s1] "=&vr" (s1)
1824	        : [w0] "vr" (w0), [w1] "vr" (w1), [w2] "vr" (w2), [w3] "vr" (w3),
1825	          [u0] "r" (u0), [u1] "r" (u1), [u2] "r" (u2), [u3] "r" (u3)
1826	        : "t0");
1827	    return acc;
1828	}
