1905	// ---- Q1_D4 gemm: 4 output rows per pass, weight stream read once for all 4 --
1906	// Same dot and the same weight stream as the gemv above; only the activation
1907	// side is new. The x4 activation block stores qs[c*4 + m] (blck_size_interleave
1908	// 1), but the dot wants row m's columns c..c+3 as ONE 32-bit element, which is
1909	// a stride-4 gather. So de-interleave the whole row tile once up front: read
1910	// the block as 32 u32 elements and peel the four byte lanes apart with vnsrl
1911	// (u32 -> 2x u16 -> 4x u8). 6 shifts + 4 stores per 32 columns, reused by every
1912	// column tile - under 1% of the inner loop - and unlike vlse8 or a segment load
1913	// it is plain RVV that cannot turn element-serial.
1914	// The u32 view is legal here: block_q8_0x4 keeps qs 4-byte aligned (d[4] is
1915	// 8 B, sizeof is 136), unlike block_q8_0 whose qs sits at offset 2 - that is
1916	// why the gemv must restage through byte ld/st and this kernel need not.
1917	//
1918	// Register budget at e32/m2 is why the per-block float accumulator of the other
1919	// kernels is gone: 4 sumf + 4 acc + dx + w + a + vneg1 already takes 24 of 32
1920	// vector registers, and one facc per row would not fit. Folding the activation
1921	// scale into dx instead costs one vfmul per group and is the same sum:
1922	//   sum_l dx * (sum_k da[k]*acc[k])  ==  sum_l sum_k (dx*da[k]) * acc[k]
1923	static void q1_gemm_64d4_vl1024(int n, float * s, size_t bs, const void * vx,
1924	                                const block_q8_0x4 * vy, int nr, int nc) {
1925	    const int    nb   = n / QK1_0;
1926	    const int    ng   = n / QK8_0;   // q8 groups per row
1927	    const size_t vl32 = 64;          // i32 lanes  = rows
1928	    const size_t vl8  = 64 * 4;      // i8  lanes  = rows x 4 columns
1929	
1930	    // the row tile's activation quants, de-interleaved: aq[m * n + column]
1931	    int8_t * aq = (int8_t *) __builtin_alloca(4 * (size_t) n);
1932	
1933	    const vint8m2_t vneg1 = __riscv_vmv_v_x_i8m2(-1, vl8);
1934	
1935	    for (int y = 0; y < nr / 4; ++y) {
1936	        const block_q8_0x4 * a_ptr = vy + (size_t) y * ng;
1937	
1938	        for (int g = 0; g < ng; ++g) {
1939	            const vuint32m1_t  q  = __riscv_vle32_v_u32m1((const uint32_t *) a_ptr[g].qs, QK8_0);
1940	            const vuint16mf2_t lo = __riscv_vnsrl_wx_u16mf2(q,  0, QK8_0);  // rows 0,1
1941	            const vuint16mf2_t hi = __riscv_vnsrl_wx_u16mf2(q, 16, QK8_0);  // rows 2,3
