1943	            __riscv_vse8_v_u8mf4(dst + 0 * (size_t) n, __riscv_vnsrl_wx_u8mf4(lo, 0, QK8_0), QK8_0);
1944	            __riscv_vse8_v_u8mf4(dst + 1 * (size_t) n, __riscv_vnsrl_wx_u8mf4(lo, 8, QK8_0), QK8_0);
