    for (int x = 0; x < nc / 64; ++x) {
        const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
        vfloat32m2_t sumf = __riscv_vfmv_v_f_f32m2(0.0f, vl32);
        for (int l = 0; l < nb; ++l) {
            q1_prefetch_block(bx, l, nb);
            const vfloat32m2_t dx     = q1_expand_fp16_64_m2(bx[l].d);
            const uint8_t *    planes = (const uint8_t *) bx[l].qs;
            vfloat32m2_t       facc   = __riscv_vfmv_v_f_f32m2(0.0f, vl32);
            for (int k = 0; k < QK1_0 / QK8_0; ++k) {
                const int        g  = l * (QK1_0 / QK8_0) + k;
                const uint32_t * aw = (const uint32_t *) (aq + (size_t) g * QK8_0);
                vint32m2_t       acc = __riscv_vmv_v_x_i32m2(0, vl32);
                // 8 column quads, taken 4 at a time: all the e8 work (mask
                // load + sign expand) first, then all the e32 work (broadcast
                // + dot), so one vsetvli covers each half instead of one per
                // step. Interleaving them is what cost 4 vsetvli per dot.
                for (int q = 0; q < QK8_0 / 4; q += 4) {
                    const uint8_t * p = planes + (size_t) (k * (QK8_0 / 4) + q) * 32;
                    const vint8m2_t w0 = __riscv_vmerge_vxm_i8m2(vneg1, 1, __riscv_vlm_v_b4(p +  0, vl8), vl8);
                    const vint8m2_t w1 = __riscv_vmerge_vxm_i8m2(vneg1, 1, __riscv_vlm_v_b4(p + 32, vl8), vl8);
                    const vint8m2_t w2 = __riscv_vmerge_vxm_i8m2(vneg1, 1, __riscv_vlm_v_b4(p + 64, vl8), vl8);
                    const vint8m2_t w3 = __riscv_vmerge_vxm_i8m2(vneg1, 1, __riscv_vlm_v_b4(p + 96, vl8), vl8);
                    acc = q1_vd4dots_x4_m2(acc, w0, w1, w2, w3,
                        aw[q + 0], aw[q + 1], aw[q + 2], aw[q + 3]);
                }
                facc = __riscv_vfmacc_vf_f32m2(facc, GGML_CPU_FP16_TO_FP32(a_ptr[g].d),
                    __riscv_vfcvt_f_x_v_f32m2(acc, vl32), vl32);
            }
            sumf = __riscv_vfmacc_vv_f32m2(sumf, dx, facc, vl32);
        }
        __riscv_vse32_v_f32m2(s + (size_t) x * 64, sumf, vl32);
    }
